"""specs_s200049.py - Sonnet-w2 family CA (generated by mkfamCA.py): this is a random object (null about 1 time in 5); 0x469870 records the SEH chain and vtable word; fs:[0] compared."""
from pilot import S
from recruits_util import rnd, obj, clear_hooks, hook_rec, pystub, seh_record, seh_chain


def _side(c, o):
    sr = seh_record(c, 2)

    def side(emu, k):
        emu.calllog.append(('vt', emu.r32(o)))
        sr(emu, k)
    return side


def _gen(c):
    clear_hooks(c)
    seh_chain(c, c.rng.choice([0, 1, 2]))
    r = c.rng
    o = rnd(c, 0x80)
    hook_rec(c, 0x469870, 0, ret=r.getrandbits(32), this=True, side=_side(c, o))
    return [o if r.random() > 0.2 else 0]


S(0x4bd9b0, 'GUESS famCA 0x4bd9b0', 'thiscall', None, ret='eax', gen=_gen, note='batch200049')
S(0x4bda50, 'GUESS famCA 0x4bda50', 'thiscall', None, ret='eax', gen=_gen, note='batch200049')
